/* ============================================================================
 * Figma runtime — bind imported layers to the brand system.
 *
 * Generated by scripts/figma-bind.mjs. Do not edit: DATA is injected from the
 * same tokens.json the HTML sheet and figma-forge read. Re-run the generator.
 *
 * Runs inside Figma's plugin sandbox. No imports, no fetch, no DOM.
 *
 * Job 1 (always): bind SOLID fills and strokes to local COLOR variables, and
 *                 apply local text styles to text nodes, by measured value.
 * Job 2 (opt-in): re-apply auto layout to flat frames using Figma's own
 *                 inferredAutoLayout heuristic. Off by default — turning it on
 *                 reflows children, so only use it on layers imported flat
 *                 (Doop's Copy for Figma), never after html.to.design.
 *
 * Order of operations in the file:
 *   1. build the system   → the plugin generated by figma-forge.mjs
 *   2. import the sheet   → <slug>-figma.html via html.to.design / Stitch
 *   3. run this plugin    → bind the imported layers back to step 1
 * ==========================================================================*/

const DATA = {
  "brand": "Vesper",
  "slug": "vesper",
  "collection": "Vesper / Colour",
  "namespace": "vs",
  "inferLayout": false,
  "palette": [
    {
      "name": "chalk",
      "hex": "#f6efe1"
    },
    {
      "name": "plate",
      "hex": "#fcf8ef"
    },
    {
      "name": "stock",
      "hex": "#e6cfa8"
    },
    {
      "name": "dusk",
      "hex": "#c9d2e4"
    },
    {
      "name": "cobalt",
      "hex": "#1b3fa2"
    },
    {
      "name": "night",
      "hex": "#0a2a6b"
    },
    {
      "name": "lampblack",
      "hex": "#0d1526"
    },
    {
      "name": "muted",
      "hex": "#565d73"
    }
  ]
};

const report = { paints: 0, strokes: 0, texts: 0, layouts: 0, created: 0, errors: [] };
const fail = (where, e) => report.errors.push(where + ': ' + ((e && e.message) || String(e)));

const round3 = (v) => Math.round(Number(v || 0) * 1000);
const rgbKey = (c) => [round3(c.r), round3(c.g), round3(c.b)].join(',');

function hexToRgb(hex) {
  let h = String(hex || '').trim().replace('#', '');
  if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  if (h.length === 8) h = h.slice(0, 6);
  const n = parseInt(h, 16);
  if (!Number.isFinite(n)) return { r: 0, g: 0, b: 0 };
  return { r: ((n >> 16) & 255) / 255, g: ((n >> 8) & 255) / 255, b: (n & 255) / 255 };
}

/* ── variables ──────────────────────────────────────────────────────────── */

async function ensureVariables() {
  const byRgb = new Map();
  const byName = new Map();
  let existing = [];
  try {
    existing = (await figma.variables.getLocalVariablesAsync('COLOR')) || [];
  } catch (e) {
    fail('getLocalVariablesAsync', e);
  }

  for (const v of existing) {
    byName.set(v.name, v);
    const vals = (v && v.valuesByMode) || {};
    for (const val of Object.values(vals)) {
      if (val && typeof val === 'object' && typeof val.r === 'number') {
        byRgb.set(rgbKey(val), v);
      }
    }
  }

  /* No system built yet. Create the primitive collection from the token file
   * so this plugin is usable on its own. Styles and components still come from
   * figma-forge; this fallback is colours only, and says so on close. */
  if (!existing.length) {
    try {
      const coll = figma.variables.createVariableCollection(DATA.collection);
      const modeId = coll.modes[0].modeId;
      coll.renameMode(modeId, 'Light');
      for (const p of DATA.palette) {
        const v = figma.variables.createVariable(p.name, coll, 'COLOR');
        const rgb = hexToRgb(p.hex);
        v.setValueForMode(modeId, { ...rgb, a: 1 });
        byRgb.set(rgbKey(rgb), v);
        byName.set(v.name, v);
        report.created++;
      }
    } catch (e) {
      fail('fallback collection', e);
    }
  }

  return { byRgb, byName };
}

/* ── text styles ────────────────────────────────────────────────────────── */

async function textStyleIndex() {
  let styles = [];
  try {
    styles = (await figma.getLocalTextStylesAsync()) || [];
  } catch (e) {
    try {
      styles = figma.getLocalTextStyles() || [];
    } catch (_) {
      styles = [];
    }
  }
  const byKey = new Map();
  for (const s of styles) {
    const size = Math.round(Number(s.fontSize) || 0);
    const family = String((s.fontName && s.fontName.family) || '').toLowerCase();
    if (size && family) byKey.set(size + '|' + family, s);
  }
  return byKey;
}

/* ── node walk ──────────────────────────────────────────────────────────── */

function collectNodes() {
  const selection = figma.currentPage.selection;
  const roots = selection && selection.length ? Array.from(selection) : Array.from(figma.currentPage.children || []);
  const out = [];
  const walk = (node) => {
    if (!node) return;
    out.push(node);
    if (Array.isArray(node.children)) for (const child of node.children) walk(child);
  };
  for (const root of roots) walk(root);
  return out;
}

function bindPaints(node, field, index) {
  const paints = node[field];
  if (!Array.isArray(paints) || !paints.length) return 0;
  let bound = 0;
  const next = paints.map((paint) => {
    if (!paint || paint.type !== 'SOLID' || !paint.color) return paint;
    if (paint.boundVariables && paint.boundVariables.color) return paint;
    const variable = index.byRgb.get(rgbKey(paint.color));
    if (!variable) return paint;
    try {
      const out = figma.variables.setBoundVariableForPaint(paint, 'color', variable);
      bound++;
      return out;
    } catch (e) {
      fail(node.name + '/' + field, e);
      return paint;
    }
  });
  if (bound) {
    try {
      node[field] = next;
    } catch (e) {
      fail(node.name + '/' + field + '/assign', e);
      return 0;
    }
  }
  return bound;
}

function bindText(node, styles) {
  if (node.type !== 'TEXT') return 0;
  const size = typeof node.fontSize === 'number' ? Math.round(node.fontSize) : 0;
  const font = node.fontName;
  const family = font && typeof font.family === 'string' ? font.family.toLowerCase() : '';
  if (!size || !family) return 0;
  const style = styles.get(size + '|' + family);
  if (!style) return 0;
  try {
    node.textStyleId = style.id;
    return 1;
  } catch (e) {
    fail(node.name + '/textStyle', e);
    return 0;
  }
}

const LAYOUT_FIELDS = [
  'layoutMode', 'paddingLeft', 'paddingRight', 'paddingTop', 'paddingBottom',
  'primaryAxisSizingMode', 'counterAxisSizingMode', 'primaryAxisAlignItems',
  'counterAxisAlignItems', 'layoutWrap', 'itemSpacing', 'counterAxisSpacing',
  'strokesIncludedInLayout', 'itemReverseZIndex',
];

function inferLayout(node) {
  if (!DATA.inferLayout) return 0;
  if (node.type !== 'FRAME' || node.layoutMode !== 'NONE') return 0;
  if (!Array.isArray(node.children) || node.children.length < 2) return 0;
  const inferred = node.inferredAutoLayout;
  if (!inferred || !inferred.layoutMode || inferred.layoutMode === 'NONE') return 0;
  let applied = 0;
  for (const key of LAYOUT_FIELDS) {
    const value = inferred[key];
    if (value === undefined || value === null) continue;
    try {
      node[key] = value;
      applied++;
    } catch (e) {
      /* a field that does not apply to this flow is skipped, not fatal */
    }
  }
  return applied ? 1 : 0;
}

/* ── main ───────────────────────────────────────────────────────────────── */

async function main() {
  const index = await ensureVariables();
  const styles = await textStyleIndex();
  const nodes = collectNodes();

  for (const node of nodes) {
    try {
      report.paints += bindPaints(node, 'fills', index);
    } catch (e) {
      fail(node.name + '/fills', e);
    }
    try {
      report.strokes += bindPaints(node, 'strokes', index);
    } catch (e) {
      fail(node.name + '/strokes', e);
    }
    try {
      report.texts += bindText(node, styles);
    } catch (e) {
      fail(node.name + '/text', e);
    }
    try {
      report.layouts += inferLayout(node);
    } catch (e) {
      fail(node.name + '/layout', e);
    }
  }

  const parts = [
    report.paints + ' fills',
    report.strokes + ' strokes',
    report.texts + ' text styles',
  ];
  if (DATA.inferLayout) parts.push(report.layouts + ' auto layouts');
  if (report.created) parts.push(report.created + ' variables created (colours only — run the build plugin for styles)');
  const summary = DATA.brand + ': bound ' + parts.join(', ') + ' across ' + nodes.length + ' layers';
  figma.notify(summary, { timeout: 8000 });
  if (report.errors.length) {
    for (const e of report.errors) console.error('[bind] ' + e);
  }
  figma.closePlugin(summary + (report.errors.length ? ' · ' + report.errors.length + ' error(s)' : ''));
}

main();
